'use client';
// `<Replaceable>` marks a part of a screen that a live preview may replace. It registers its key and source file; while an overlay for
// its key is active (enabled, shown and not expired) it renders a placeholder slot and the original. Otherwise the original alone.
// The frame that renders the replacement is a later part (PR 2); until then the slot says the preview is unavailable.
import { useContext, useEffect } from 'react';
import type { ReactNode } from 'react';
import { PreviewContext } from './provider';
import { previewText } from './preview-text';

export interface ReplaceableEntry {
  readonly key: string;
  readonly filePath: string;
}

const replaceables = new Map<string, ReplaceableEntry>();

/** The key to source file mapping of the mounted replaceables. The host resolves a file from a key here. */
export function listReplaceables(): readonly ReplaceableEntry[] {
  return [...replaceables.values()];
}

export interface ReplaceableProps {
  readonly id: string;
  readonly source: string;
  /** Serialisable props the replacement receives (used by the frame, PR 2). */
  readonly props?: Readonly<Record<string, unknown>>;
  readonly children: ReactNode;
}

export function Replaceable({ id, source, children }: ReplaceableProps) {
  const { enabled, overlays, shown, locale } = useContext(PreviewContext);
  useEffect(() => {
    replaceables.set(id, { key: id, filePath: source });
    return () => { replaceables.delete(id); };
  }, [id, source]);
  const active = enabled && shown && overlays.some(overlay => overlay.key === id);
  if (!active) return <>{children}</>;
  return <>
    <div data-boring-preview-slot={id} className="rounded-md border border-dashed border-border p-3 text-sm text-muted-foreground">{previewText(locale).unavailable}</div>
    {children}
  </>;
}

// The live-preview overlay store, pure: the storage is injected, so a test runs it without a DOM. Overlays live in sessionStorage, one key
// per app and release, and never leave the browser. Each lasts two hours from its creation; a new release is a new key, so the old
// overlays are not served. Every storage access is guarded: a blocked or throwing storage reads as empty and writes report false.
export const PREVIEW_TTL_MS = 2 * 60 * 60 * 1000;

export interface PreviewOverlay {
  readonly key: string;
  readonly source: string;
  readonly createdAt: number;
  /** The tool call id of the `boring.preview` result it came from (the PM's record of the change). */
  readonly previewId?: string | undefined;
}

export interface OverlayStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

export function storageKey(appId: string, release: string): string {
  return `boring.preview:${appId}:${release}`;
}

export function fresh(overlays: readonly PreviewOverlay[], now: number): PreviewOverlay[] {
  return overlays.filter(overlay => now - overlay.createdAt < PREVIEW_TTL_MS);
}

function valid(value: unknown): value is PreviewOverlay {
  if (typeof value !== 'object' || value === null) return false;
  const overlay = value as Record<string, unknown>;
  return typeof overlay.key === 'string' && typeof overlay.source === 'string' && typeof overlay.createdAt === 'number'
    && (overlay.previewId === undefined || typeof overlay.previewId === 'string');
}

export function readOverlays(storage: OverlayStorage | undefined, appId: string, release: string, now: number): PreviewOverlay[] {
  try {
    const raw = storage?.getItem(storageKey(appId, release));
    if (!raw) return [];
    const parsed: unknown = JSON.parse(raw);
    return Array.isArray(parsed) ? fresh(parsed.filter(valid), now) : [];
  } catch {
    return [];
  }
}

/** An empty list removes the key. Returns false when nothing could be stored (no storage, or it throws). */
export function writeOverlays(storage: OverlayStorage | undefined, appId: string, release: string, overlays: readonly PreviewOverlay[]): boolean {
  if (!storage) return false;
  try {
    const key = storageKey(appId, release);
    if (overlays.length === 0) storage.removeItem(key);
    else storage.setItem(key, JSON.stringify(overlays));
    return true;
  } catch {
    return false;
  }
}

/** The moment the earliest overlay expires, or undefined with none. */
export function nextExpiry(overlays: readonly PreviewOverlay[]): number | undefined {
  if (overlays.length === 0) return undefined;
  return Math.min(...overlays.map(overlay => overlay.createdAt)) + PREVIEW_TTL_MS;
}

export function sessionStorageOf(): OverlayStorage | undefined {
  try {
    return typeof window === 'undefined' ? undefined : window.sessionStorage;
  } catch {
    return undefined;
  }
}

'use client';
// The live-preview provider: the overlays of one app and release, the shown toggle and the share note. The shell mounts it (AppShell's
// `preview` prop); without it nothing is previewed. Nothing is sent over the network: a share goes only to the host's `onShare`.
import { createContext, useContext, useEffect, useState } from 'react';
import type { ReactNode } from 'react';
import { fresh, nextExpiry, readOverlays, sessionStorageOf, writeOverlays } from './store';
import type { PreviewOverlay } from './store';
import type { PreviewLocale } from './preview-text';

export interface PreviewShare {
  readonly key: string;
  /** The tool call id of the change's `boring.preview` result, when the overlay came from one. */
  readonly previewId: string | undefined;
  /** The build SHA the overlay was made against (the app's `preview.release`). */
  readonly release: string;
}

export interface PreviewShared {
  readonly prUrl?: string | undefined;
}

export interface PreviewSettings {
  readonly appId: string;
  readonly release: string;
  readonly enabled: boolean;
  readonly locale?: PreviewLocale | undefined;
  /** Proposes the change. The overlay is cleared once it resolves; a rejection keeps it, so the viewer can close it. */
  readonly onShare?: ((share: PreviewShare) => Promise<PreviewShared | void>) | undefined;
}

export interface PreviewStore {
  readonly enabled: boolean;
  readonly locale: PreviewLocale;
  /** The live overlays (expired ones are gone). Empty while disabled. */
  readonly overlays: readonly PreviewOverlay[];
  readonly shown: boolean;
  readonly setShown: (shown: boolean) => void;
  readonly add: (overlay: { readonly key: string; readonly source: string; readonly previewId?: string }) => void;
  readonly remove: (key: string) => void;
  readonly clearAll: () => void;
  readonly canShare: boolean;
  readonly share: (key: string) => Promise<void>;
  readonly note: PreviewShared | undefined;
}

const none: PreviewStore = {
  enabled: false, locale: 'en', overlays: [], shown: true, setShown: () => {}, add: () => {}, remove: () => {}, clearAll: () => {},
  canShare: false, share: () => Promise.resolve(), note: undefined,
};

export const PreviewContext = createContext<PreviewStore>(none);

/** The live-preview store of the nearest provider: `add`, `remove`, `clearAll`, `shown`, `setShown`, plus the overlays. */
export function usePreviewOverlays(): PreviewStore {
  return useContext(PreviewContext);
}

// setTimeout takes a 32-bit delay; a later expiry is re-armed when the timer fires.
const MAX_DELAY = 2_147_483_647;

export function PreviewProvider({ settings, children }: { readonly settings: PreviewSettings; readonly children: ReactNode }) {
  const { appId, release, enabled, onShare } = settings;
  const locale = settings.locale ?? 'en';
  const [stored, setStored] = useState<readonly PreviewOverlay[]>(() => enabled ? readOverlays(sessionStorageOf(), appId, release, Date.now()) : []);
  const [shown, setShown] = useState(true);
  const [note, setNote] = useState<PreviewShared | undefined>();

  useEffect(() => {
    setStored(enabled ? readOverlays(sessionStorageOf(), appId, release, Date.now()) : []);
  }, [appId, release, enabled]);

  // Expiry: the overlays drop out at render, and a timer re-reads them at the earliest end, so an idle page loses them on time too.
  useEffect(() => {
    const at = nextExpiry(stored);
    if (at === undefined) return;
    const timer = setTimeout(() => setStored(current => fresh(current, Date.now())), Math.min(Math.max(at - Date.now(), 0) + 1, MAX_DELAY));
    return () => clearTimeout(timer);
  }, [stored]);

  const overlays = enabled ? fresh(stored, Date.now()) : [];

  // Every change writes the storage from the current list (a no-op write when the storage is blocked) and then updates the state.
  const mutate = (change: (current: readonly PreviewOverlay[]) => PreviewOverlay[]) => setStored(current => {
    const next = change(fresh(current, Date.now()));
    writeOverlays(sessionStorageOf(), appId, release, next);
    return next;
  });

  const add: PreviewStore['add'] = overlay => {
    if (!enabled) return;
    setNote(undefined);
    setShown(true);
    mutate(current => [...current.filter(item => item.key !== overlay.key), { key: overlay.key, source: overlay.source, createdAt: Date.now(), previewId: overlay.previewId }]);
  };

  const remove: PreviewStore['remove'] = key => mutate(current => current.filter(item => item.key !== key));

  const clearAll: PreviewStore['clearAll'] = () => {
    setNote(undefined);
    mutate(() => []);
  };

  const share: PreviewStore['share'] = async key => {
    const overlay = overlays.find(item => item.key === key);
    if (!overlay || !onShare) return;
    let result: PreviewShared | void;
    try {
      result = await onShare({ key, previewId: overlay.previewId, release });
    } catch {
      return;
    }
    remove(key);
    setNote({ prUrl: result?.prUrl });
  };

  const value: PreviewStore = {
    enabled, locale, overlays, shown, setShown, add, remove, clearAll, canShare: Boolean(onShare), share, note,
  };
  return <PreviewContext.Provider value={value}>{children}</PreviewContext.Provider>;
}

'use client';
// The « Prévisualisation » banner and the share note. Both render nothing when the preview is off; the banner also needs an overlay.
import { useContext } from 'react';
import { PreviewContext } from './provider';
import { previewText } from './preview-text';

export function PreviewStatus() {
  const preview = useContext(PreviewContext);
  const t = previewText(preview.locale);
  if (!preview.enabled) return null;
  return <>
    {preview.overlays.length > 0 && <div data-testid="preview-banner" role="region" aria-label={t.banner}
      className="flex flex-wrap items-center gap-2 border-b border-border bg-muted px-3 py-2 text-sm text-foreground">
      <span className="font-medium">{t.banner}</span>
      {preview.overlays.map(overlay => <span key={overlay.key} className="inline-flex items-center gap-1">
        <code className="text-xs">{overlay.key}</code>
        {preview.canShare && <button type="button" onClick={() => void preview.share(overlay.key)}
          className="rounded-md px-2 py-1 underline-offset-4 hover:underline pointer-coarse:min-h-11 pointer-coarse:min-w-11">{t.share}</button>}
        <button type="button" data-testid={`preview-close-${overlay.key}`} aria-label={t.closeKey(overlay.key)} onClick={() => preview.remove(overlay.key)}
          className="rounded-md px-2 py-1 hover:bg-background pointer-coarse:min-h-11 pointer-coarse:min-w-11">×</button>
      </span>)}
      <button type="button" onClick={() => preview.setShown(!preview.shown)}
        className="rounded-md px-2 py-1 underline-offset-4 hover:underline pointer-coarse:min-h-11 pointer-coarse:min-w-11">{preview.shown ? t.hide : t.show}</button>
      <button type="button" onClick={() => preview.clearAll()}
        className="rounded-md px-2 py-1 underline-offset-4 hover:underline pointer-coarse:min-h-11 pointer-coarse:min-w-11">{t.cancelAll}</button>
    </div>}
    {preview.note && <div data-testid="preview-note" role="status" className="border-b border-border bg-muted px-3 py-2 text-sm text-muted-foreground">
      {t.proposed}{preview.note.prUrl && <> — <a href={preview.note.prUrl} target="_blank" rel="noreferrer" className="underline underline-offset-4">{t.seeProposal}</a></>}
    </div>}
  </>;
}

'use client';
// The chat card for a `boring.preview` tool result. Nothing applies until the viewer clicks: the click adds the overlay.
import { useContext } from 'react';
import type { ChatCard } from '../pi-chat/rows';
import { PreviewContext } from './provider';
import { previewText } from './preview-text';

/** The parts of a tool result and of its call that the card reads (the chat passes pi's own message types). */
export interface PreviewResult {
  readonly details?: unknown;
}

function PreviewButton({ overlay, previewId }: { readonly overlay: { readonly key: string; readonly source: string }; readonly previewId: string }) {
  const preview = useContext(PreviewContext);
  if (!preview.enabled) return null;
  const t = previewText(preview.locale);
  return <button type="button" onClick={() => preview.add({ key: overlay.key, source: overlay.source, previewId })}
    className="inline-flex min-h-9 items-center gap-1 rounded-md border border-border px-3 py-1 text-sm hover:bg-muted pointer-coarse:min-h-11">
    {t.preview} <code className="text-xs">{overlay.key}</code>
  </button>;
}

/** The card for a finished `boring.preview` result (`details: { kind, key, source }`), or undefined for any other result. */
export function previewCardFor(result: PreviewResult | undefined, call: { readonly id: string }): ChatCard | undefined {
  const details = result?.details as { readonly kind?: unknown; readonly key?: unknown; readonly source?: unknown } | undefined;
  if (details?.kind !== 'boring.preview' || typeof details.key !== 'string' || typeof details.source !== 'string') return undefined;
  return { content: <PreviewButton overlay={{ key: details.key, source: details.source }} previewId={call.id} /> };
}

// The live preview's own words, one fixed set of keys per language (as the app shell's text.ts).
export type PreviewLocale = 'en' | 'fr';

export interface PreviewText {
  /** The banner's title. */
  readonly banner: string;
  /** The toggle that hides or shows the overlays. */
  readonly show: string;
  readonly hide: string;
  /** Removes every overlay at once. */
  readonly cancelAll: string;
  /** Proposes the change for review (shown only when the host gives `onShare`). */
  readonly share: string;
  /** Shown after a share: the change is proposed, not applied. */
  readonly proposed: string;
  readonly seeProposal: string;
  /** The neutral box a replaced component shows in its slot. */
  readonly unavailable: string;
  /** The chat card's button label. */
  readonly preview: string;
  readonly closeKey: (key: string) => string;
}

const en: PreviewText = {
  banner: 'Preview',
  show: 'Show',
  hide: 'Hide',
  cancelAll: 'Cancel all',
  share: 'Share',
  proposed: 'Proposed — visible once deployed',
  seeProposal: 'See the proposal',
  unavailable: 'Preview unavailable',
  preview: 'Preview',
  closeKey: key => `Close the preview of ${key}`,
};

const fr: PreviewText = {
  banner: 'Prévisualisation',
  show: 'Afficher',
  hide: 'Masquer',
  cancelAll: 'Tout annuler',
  share: 'Partager',
  proposed: 'Proposé — visible après mise en ligne',
  seeProposal: 'Voir la proposition',
  unavailable: 'Aperçu indisponible',
  preview: 'Prévisualiser',
  closeKey: key => `Fermer la prévisualisation de ${key}`,
};

export function previewText(locale: PreviewLocale): PreviewText {
  return locale === 'fr' ? fr : en;
}

// The live preview (registry/live-preview): replaceable parts, the overlay store, the shell's banner and the chat card. The frame that
// runs a replacement is a later part; nothing here executes source.
export { Replaceable, listReplaceables } from './replaceable';
export type { ReplaceableEntry, ReplaceableProps } from './replaceable';
export { PreviewProvider, usePreviewOverlays } from './provider';
export type { PreviewSettings, PreviewShare, PreviewShared, PreviewStore } from './provider';
export { PreviewStatus } from './status';
export { previewCardFor } from './card';
export type { PreviewResult } from './card';
export { PREVIEW_TTL_MS } from './store';
export type { PreviewOverlay } from './store';
export type { PreviewLocale } from './preview-text';
